def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find connected nonzero tile components.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            comps.append((min(rs), min(cs), max(rs), max(cs)))

    # The full square components reveal the tile size.
    squares = [(a, b, d - a + 1) for a, b, d, e in comps
               if d - a == e - b]
    if not squares:
        return out
    size = max(n for _, _, n in squares)

    tiles = []
    for r, c, n in squares:
        if n != size or r + size > h or c + size > w:
            continue
        inner = [grid[y][x]
                 for y in range(r + 1, r + size - 1)
                 for x in range(c + 1, c + size - 1)]
        if not inner:
            continue
        counts = {}
        for v in inner:
            counts[v] = counts.get(v, 0) + 1
        color = max(counts, key=counts.get)
        tiles.append((r, c, color))

    if not tiles:
        return out

    counts = {}
    for _, _, color in tiles:
        counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    # Join matching non-background tile colors through the zero gutters.
    for r in sorted(set(t[0] for t in tiles)):
        row_tiles = sorted((c, color) for rr, c, color in tiles if rr == r)
        for color in counts:
            if color == background:
                continue
            positions = [c for c, col in row_tiles if col == color]
            if len(positions) < 2:
                continue
            lo, hi = min(positions), max(positions)
            for y in range(r + 1, r + size - 1):
                for x in range(lo + size, hi):
                    if grid[y][x] == 0:
                        out[y][x] = color

    for c in sorted(set(t[1] for t in tiles)):
        col_tiles = sorted((r, color) for r, cc, color in tiles if cc == c)
        for color in counts:
            if color == background:
                continue
            positions = [r for r, col in col_tiles if col == color]
            if len(positions) < 2:
                continue
            lo, hi = min(positions), max(positions)
            for x in range(c + 1, c + size - 1):
                for y in range(lo + size, hi):
                    if grid[y][x] == 0:
                        out[y][x] = color

    return out
